def comps8(g,col):
    seen=set(); out=[]
    for i,r in enumerate(g):
        for j,v in enumerate(r):
            if v==col and (i,j) not in seen:
                st=[(i,j)];comp=[];seen.add((i,j))
                while st:
                    y,x=st.pop();comp.append((y,x))
                    for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=y+dy,x+dx
