    # normalize: remove leading/all-zero rows/cols? no—keep. Check transforms
    def T(A,k):  # flips/rot
        res=A
        for _ in range(k):
            res=[[res[j][i] for i in range(len(res[0]))] for j in range(len(res))]
            res=[list(r) for r in zip(*res[::-1])]
        return res
    hits=[T(m,k) for k in range(4)]+[ [m[j][::-1] for j in range(len(m))] ]+[ [m[::1][j][::-1] for j in range(len(m))] ]
    flat=[T(m,k) for k in range(4)]
    ok = any(h==go for h in flat+hits)
    print('cells',len(c),'bboxsize',(mx-mn+1,mymax-my+1),'transform-match?',ok)

