    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load(); print(sorted(G))
# The last submitted grid was already judged correct. Rule: component with bbox matching output dims; tie-break: most cells. Just confirm f works and produce test output programmatically.
from collections import deque
def f(gi, outdims=None):
    col=next(v for v in {x for r in gi for x in r} if v!=0)
    seen=set(); cs=[]
    for i,r in enumerate(gi):
        for j,v in enumerate(r):
            if v==col and (i,j) not in seen:
                st=[(i,j)];comp=[];seen.add((i,j))
                while st:
                    y,x=st.pop();comp.append((y,x))
                    for dy in (-1,0,1):
                        for dx in (-1,0,1):
                            ny,nx=y+dy,x+dx
                            if (dy or dx) and 0<=ny<len(gi) and 0<=nx<len(gi[0]) and gi[ny][nx]==col and (ny,nx) not in seen:
                                seen.add((ny,nx));st.append((ny,nx))
                cs.append(comp)
    best=None
    for c in cs:
        ys=[y for y,_ in c]; xs=[x for _,x in c]
        mn,mx,my,mymax=min(xs),max(xs),min(ys),max(ys)
        pat=[[gi[y][x] for x in range(mn,mx+1)] for y in range(my,mymax+1)]
        hh,ww=(mymax-my+1,mx-mn+1)
        key=(hh==outdims[0] and ww==outdims[1], len(pat)*len(pat[0]), len(c))
        if best is None or key > best[0]: best=(key,pat,c)
    return [[int(v) for v in r] for r in best[1]],best[2]
for n in ['Demo pair 1','Demo pair 2','Demo pair 3']:
    gi=G[n+' input']; go=G[n+' output']
    p,c=f(gi,len(go)),None
    print(n, 'match' if p==go else 'FAIL', c)
p,c=f(G['Test input'],None); print(json.dumps(p))

